const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const deathValley = ee.Geometry.Polygon([
    [-117.2, 36.8],
    [-116.2, 36.8], 
    [-116.2, 36.2],
    [-117.2, 36.2]
  ]);

  const date1 = '2022-07-11';
  const date2 = '2022-08-07';

  // 2. Data Acquisition
  const getWaterImage = function(targetDate) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(deathValley)
      .filterDate(ee.Date(targetDate).advance(-1, 'day'), 
                  ee.Date(targetDate).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    return collection.median()
      .clip(deathValley);
  };

  const img1 = getWaterImage(date1);
  const img2 = getWaterImage(date2);

  // Check if collections are empty
  const checkCollection = function(targetDate) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(deathValley)
      .filterDate(ee.Date(targetDate).advance(-1, 'day'), 
                  ee.Date(targetDate).advance(1, 'day'));
    return col.size();
  };

  const count1 = checkCollection(date1).getInfo();
  const count2 = checkCollection(date2).getInfo();

  print(`${date1} Images: ${count1}`);
  print(`${date2} Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // 3. Water Detection Processing
  const calculateWaterArea = function(img) {
    // Calculate NDWI
    const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Apply water threshold (NDWI > 0.0)
    const waterMask = ndwi.gt(0.0);

    // Count water pixels
    const stats = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: deathValley,
      scale: 100,
      maxPixels: 1e9
    });

    return stats.get('NDWI');
  };

  const water1 = calculateWaterArea(img1).getInfo();
  const water2 = calculateWaterArea(img2).getInfo();

  print(`July 11 Water Pixels: ${water1}`);
  print(`August 7 Water Pixels: ${water2}`);

  // 4. Validation & Final Answer
  if (water1 === null || water2 === null || 
      isNaN(water1) || isNaN(water2) ||
      water1 < 0 || water2 < 0) {
    print("<answer>C3</answer>");
  } else if (water1 === 0 || water2 === 0) {
    print("<answer>C2</answer>");
  } else if (water2 > water1) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
